(()=>{
'use strict';
const $=id=>document.getElementById(id),canvas=$('painting'),ctx=canvas.getContext('2d'),image=new Image();
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const scenes=[{"name": "慈溪", "x": 0.035, "y": 0.39, "text": "慈溪位于宁波市域北部，是观察城乡协同发展与江南田园风貌的一处窗口。画卷以村落、田畴和远山，展开宁波城市故事的序章。", "view": "田园与村落", "url": "https://baike.baidu.com/search/word?word=%E6%85%88%E6%BA%AA", "source": "百度百科搜索"}, {"name": "古县城", "x": 0.14, "y": 0.47, "text": "古县城承载着宁波地方历史与传统街巷文化。画中的城墙、古塔和民居共同构成古城风貌，可在这里停留，细看街区与建筑的层次。", "view": "城墙、古塔与民居", "url": "https://baike.baidu.com/search/word?word=%E6%85%88%E5%9F%8E%E5%8F%A4%E5%8E%BF%E5%9F%8E", "source": "百度百科搜索"}, {"name": "月湖", "x": 0.255, "y": 0.57, "text": "月湖位于宁波老城，是历史文化景观与城市水系相互交织的地方。湖岸亭台、洲渚与林木，呼应了这片水域长久积累的人文气息。", "view": "湖心亭台与洲渚", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E6%9C%88%E6%B9%96", "source": "百度百科搜索"}, {"name": "鼓楼", "x": 0.372, "y": 0.5, "text": "宁波鼓楼是城市历史的重要地标，周边街区延续着老城生活与商业记忆。画中将楼阁、城门和街巷组合成一处鲜明的历史节点。", "view": "城门楼阁", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E9%BC%93%E6%A5%BC", "source": "百度百科搜索"}, {"name": "城隍庙", "x": 0.452, "y": 0.59, "text": "宁波城隍庙一带汇聚传统建筑、民俗文化与市井生活。画卷以重檐屋顶和密集街巷，呈现这里热闹而亲切的老城气质。", "view": "传统庙宇与街巷", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E5%9F%8E%E9%9A%8D%E5%BA%99", "source": "百度百科搜索"}, {"name": "老外滩", "x": 0.53, "y": 0.62, "text": "老外滩位于宁波三江口一带，是了解城市近代历史和滨江风貌的窗口。沿江建筑与码头记忆，在画中与宽阔的江面相互映衬。", "view": "沿江近代建筑", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E8%80%81%E5%A4%96%E6%BB%A9", "source": "百度百科搜索"}, {"name": "甬江", "x": 0.614, "y": 0.64, "text": "甬江是宁波重要的城市水脉，连接城市生活、航运与港口发展的记忆。画中的桥梁、船只和两岸建筑，呈现江与城共同生长的景象。", "view": "跨江大桥与航船", "url": "https://baike.baidu.com/search/word?word=%E7%94%AC%E6%B1%9F", "source": "百度百科搜索"}, {"name": "东部新城", "x": 0.725, "y": 0.47, "text": "东部新城呈现宁波现代城市建设的面貌。高层楼宇、公共空间与交通网络，在画中形成开阔的城市天际线，与左侧的历史街区遥相呼应。", "view": "现代城市天际线", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E4%B8%9C%E9%83%A8%E6%96%B0%E5%9F%8E", "source": "百度百科搜索"}, {"name": "宁波博物馆", "x": 0.805, "y": 0.66, "text": "宁波博物馆是了解城市历史文化的重要场所。画中以具有辨识度的建筑体量作为节点，邀请游人从城市景观走向宁波的文化记忆。", "view": "临水博物馆建筑", "url": "https://baike.baidu.com/search/word?word=%E5%AE%81%E6%B3%A2%E5%8D%9A%E7%89%A9%E9%A6%86", "source": "百度百科搜索"}, {"name": "东钱湖", "x": 0.936, "y": 0.45, "text": "东钱湖是宁波著名的湖泊风景区，湖面、群山和沿岸村落共同构成开阔的山水空间。画卷以湖岛与帆影收束城市漫游，让视线重新回到自然。", "view": "湖光、山色与帆影", "url": "https://baike.baidu.com/search/word?word=%E4%B8%9C%E9%92%B1%E6%B9%96", "source": "百度百科搜索"}];
const state={p:0,target:0,zoom:1,auto:false,snow:!reduce.matches,mist:!reduce.matches,spots:true,ready:false};
let W=1,H=1,scale=1,world=1,camera=0,top=0,drag=null,last=0,clock=0,ripples=[],current=-1,readyTime=0;
let pins=scenes.map((s,i)=>{const b=document.createElement('button');b.className='pin';b.setAttribute('aria-label','查看'+s.name);b.innerHTML='·<span>'+s.name+'</span>';b.onclick=()=>go(i,true);$('markers').append(b);const stop=document.createElement('button');stop.textContent=s.name;stop.onclick=()=>go(i,true);$('stops').append(stop);return b;});
function geometry(){scale=H/image.height*state.zoom;world=image.width*scale;camera=state.p*Math.max(0,world-W);top=(H-image.height*scale)*.5;}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;const d=Math.min(devicePixelRatio||1,2,Math.sqrt(2400000/(W*H)));canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);if(state.ready)geometry();}
new ResizeObserver(resize).observe(canvas);
function setAuto(value){state.auto=value;$('play').textContent=value?'暂停漫游':'开始漫游';$('play').setAttribute('aria-pressed',value);}
function seek(p){setAuto(false);state.target=clamp(p,0,1);if(reduce.matches)state.p=state.target;}
function go(i,open){const s=scenes[i];geometry();seek((s.x*world-W*.5)/Math.max(1,world-W));if(open){state.p=state.target;$('detail-title').textContent=s.name;$('detail-text').textContent=s.text;$('detail-view').textContent='画中：'+s.view;$('detail-link').href=s.url;$('detail-link').textContent='了解更多 · '+s.source+' ↗';paint(clock);ui();$('detail').showModal();}}
function ui(){geometry();const center=(camera+W*.5)/world;let near=0;scenes.forEach((s,i)=>{if(Math.abs(s.x-center)<Math.abs(scenes[near].x-center))near=i;const x=s.x*world-camera,y=top+s.y*image.height*scale;pins[i].hidden=!state.spots||x<42||x>W-42||y<70||y>H-65;pins[i].style.left=x+'px';pins[i].style.top=y+'px';});if(near!==current){current=near;[...$('stops').children].forEach((b,i)=>b.setAttribute('aria-current',i===near));}$('progress').textContent='已游 '+Math.round(state.p*100)+'%';$('position').value=Math.round(state.p*1000);$('map-window').style.width=Math.min(1,W/world)*100+'%';$('map-window').style.left=(camera/world)*100+'%';}
// Conservative hand-placed water areas in normalized source coordinates.
const water=[[[.195,.62],[.22,.53],[.26,.55],[.30,.64],[.33,.80],[.31,.98],[.22,.98]],[[.565,.72],[.58,.60],[.63,.62],[.69,.70],[.75,1],[.64,1]],[[.82,.43],[.88,.43],[.92,.39],[.97,.43],[1,.50],[1,.84],[.95,.79],[.91,.73],[.85,.64]]];
function pointWater(x,y){return water.some(poly=>{let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;});}
function waterPath(){ctx.beginPath();for(const poly of water){poly.forEach((p,i)=>{const x=p[0]*world-camera,y=p[1]*image.height*scale+top;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();}}
function paint(t){geometry();ctx.clearRect(0,0,W,H);const sourceW=W/scale,sourceX=camera/scale,sourceY=-top/scale;ctx.drawImage(image,sourceX,sourceY,sourceW,H/scale,0,0,W,H);
 ctx.save();waterPath();ctx.clip();
 if(!reduce.matches){ctx.strokeStyle='rgba(232,241,244,.20)';ctx.lineWidth=.6;for(let i=0;i<34;i++){const x=((i*.073+Math.sin(t*.12+i)*.001)%1)*world-camera,y=top+image.height*scale*(.78+(i%9)*.024);ctx.beginPath();ctx.ellipse(x,y,(12+(i%5)*6)*scale,1,0,0,Math.PI*2);ctx.stroke();}}
 ripples=ripples.filter(r=>t-r.born<3);for(const r of ripples){const age=t-r.born;ctx.strokeStyle=`rgba(240,246,248,${.7*(1-age/3)})`;ctx.lineWidth=1;for(let j=0;j<3;j++){const radius=Math.max(0,age*26-j*9);ctx.beginPath();ctx.ellipse(r.x*world-camera,top+r.y*image.height*scale,radius,radius*.22,0,0,Math.PI*2);ctx.stroke();}}
 ctx.restore();
 if(state.mist){ctx.save();for(let i=0;i<4;i++){let x=W*(i/3)+Math.sin(t*.06+i)*W*.12,y=H*(.67+i*.03);const g=ctx.createRadialGradient(x,y,0,x,y,W*.34);g.addColorStop(0,'rgba(229,237,239,.13)');g.addColorStop(1,'rgba(229,237,239,0)');ctx.fillStyle=g;ctx.fillRect(0,H*.48,W,H*.52);}ctx.restore();}
 if(state.snow){ctx.save();waterPath();ctx.clip();ctx.fillStyle='#fff';const count=Math.min(140,Math.floor(W/10));for(let i=0;i<count;i++){let depth=(i%4+1)/4;let x=((((i*73.37+t*(9+depth*13)+Math.sin(t*.4+i)*8)%(W+40))+(W+40))%(W+40))-20,y=H*(.62+(i%13)*.029)+Math.sin(t*.3+i)*2;ctx.globalAlpha=.12+depth*.18;ctx.beginPath();ctx.arc(x,y,.6+depth*1.2,0,Math.PI*2);ctx.fill();}ctx.restore();}}
function frame(now){requestAnimationFrame(frame);if(!state.ready||document.hidden)return;if(now-last<32)return;const dt=Math.min(.065,(now-last)/1000||.032);last=now;clock+=dt;const modal=$('info').open||$('detail').open;if(state.auto&&!modal){state.target=clamp(state.target+dt/160,0,1);if(state.target>=1&&state.p>.999)setAuto(false);}if(!drag)state.p+= (state.target-state.p)*(reduce.matches?1:1-Math.exp(-dt*7));if(!modal){paint(clock);ui();}}
canvas.addEventListener('pointerdown',e=>{if(!state.ready)return;setAuto(false);drag={id:e.pointerId,x:e.clientX,y:e.clientY,p:state.p,moved:false};canvas.setPointerCapture(e.pointerId);$('viewer').classList.add('dragging');});
canvas.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>5)drag.moved=true;if(drag.moved){state.p=state.target=clamp(drag.p-dx/Math.max(1,world-W),0,1);}});
canvas.addEventListener('pointerup',e=>{if(!drag)return;if(!drag.moved){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left+camera)/world,y=(e.clientY-r.top-top)/(image.height*scale);if(pointWater(x,y))ripples.push({x,y,born:clock});}drag=null;$('viewer').classList.remove('dragging');});
canvas.addEventListener('pointercancel',()=>{drag=null;$('viewer').classList.remove('dragging');});
$('viewer').addEventListener('keydown',e=>{if(e.target!==$('viewer')&&e.target!==canvas)return;if(['ArrowLeft','ArrowRight',' ','Home','End'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')seek(state.target-.035);if(e.key==='ArrowRight')seek(state.target+.035);if(e.key==='Home')seek(0);if(e.key==='End')seek(1);if(e.key===' ')setAuto(!state.auto);});
$('play').onclick=()=>{if(!state.ready)return;if(state.p>.999)state.p=state.target=0;setAuto(!state.auto);};$('back').onclick=()=>seek(state.target-.07);$('next').onclick=()=>seek(state.target+.07);$('reset').onclick=()=>seek(0);$('position').oninput=e=>seek(e.target.value/1000);
$('zoom').oninput=e=>{const center=(camera+W*.5)/world;state.zoom=+e.target.value;geometry();state.p=state.target=clamp((center*world-W*.5)/Math.max(1,world-W),0,1);setAuto(false);};
for(const key of ['snow','mist','spots']){const update=()=>{$(key).setAttribute('aria-pressed',state[key]);$(key).textContent=({snow:'波光',mist:'江雾',spots:'景点'})[key]+' · '+(state[key]?'开':'关');};$(key).onclick=()=>{state[key]=!state[key];update();};update();}
reduce.addEventListener('change',()=>{if(reduce.matches){state.snow=false;state.mist=false;setAuto(false);for(const key of ['snow','mist']){$(key).setAttribute('aria-pressed',false);$(key).textContent=({snow:'波光',mist:'江雾'})[key]+' · 关';}}});
$('about').onclick=()=>{setAuto(false);$('info').showModal();};$('continue').onclick=()=>{$('detail').close();$('viewer').focus();};
$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('viewer').requestFullscreen)await $('viewer').requestFullscreen();else $('hint').textContent='此浏览器不支持全屏，请横屏赏画';}catch{$('hint').textContent='未能进入全屏，可继续拖动赏画';}};
document.addEventListener('fullscreenchange',()=>{$('full').textContent=document.fullscreenElement?'退出全屏 ⛶':'全屏赏画 ⛶';});
image.onload=()=>{state.ready=true;readyTime=performance.now();$('loading').hidden=true;resize();paint(0);ui();};image.onerror=()=>{$('loading').textContent='画卷未能载入，请检查 assets/scroll.png 后刷新。';};image.src='assets/scroll.png';requestAnimationFrame(frame);

const music=new Audio('assets/yudabajiao.ogg');music.loop=true;music.volume=.42;const musicButton=$('music');musicButton.onclick=async()=>{if(music.paused){try{await music.play();musicButton.textContent='♫ 关闭音乐';musicButton.setAttribute('aria-pressed','true');}catch(error){musicButton.textContent='音乐加载失败';musicButton.setAttribute('aria-pressed','false');}}else{music.pause();musicButton.textContent='♫ 开启音乐';musicButton.setAttribute('aria-pressed','false');}};
})();
